225→  // ── Shared: build widget inner HTML + wire up events ────────────────────────
226→  function buildWidgetInner(wid, cfg, btnLabel) {
227→    return (
228→      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
229→      '<div class="zcc-row">' +
230→        '<input class="zcc-input" type="text" id="' + wid + '-inp"' +
231→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
232→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
233→        '<button class="zcc-btn" id="' + wid + '-btn" type="button">' + esc(btnLabel) + "</button>" +
234→      "</div>" +
235→      '<div id="' + wid + '-res"></div>'
236→    );
237→  }
238→
239→  function wireWidget(wid, cfg, API_BASE, SHOP) {
240→    var inp = document.getElementById(wid + "-inp");
241→    var btn = document.getElementById(wid + "-btn");
242→    var res = document.getElementById(wid + "-res");
243→    var btnLabel = cfg.buttonText;
244→    if (!inp || !btn || !res) return;
245→
246→    function normalizeZip(raw) {
247→      var z = raw.trim().toUpperCase();
248→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
249→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
250→      return z;
251→    }
252→
253→    function checkZip() {
254→      var zip = normalizeZip(inp.value);
255→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
256→      if (!zip) { inp.focus(); return; }
257→
258→      btn.disabled = true;
259→      btn.textContent = "\u2026";
260→      res.innerHTML = "";
261→
262→      fetch(
263→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
264→          "&zip=" + encodeURIComponent(zip)
265→      )
266→        .then(function (r) { return r.json(); })
267→        .then(function (data) {
268→          btn.disabled = false;
269→          btn.textContent = btnLabel;
270→
271→          // Store validation result for cart page
272→          try {
273→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
274→            sessionStorage.setItem('zcc:zip', zip);
275→            sessionStorage.setItem('zcc:shop', SHOP);
276→            // Fire custom event for other scripts to listen to
277→            window.dispatchEvent(new CustomEvent('zcc:validated', {
278→              detail: { valid: data.allowed, zip: zip }
279→            }));
280→          } catch(e) { /* sessionStorage may be unavailable */ }
281→
282→          if (data.allowed) {
283→            var html = '<div class="zcc-result ok">' + esc(data.message);
284→            if (cfg.showEta && data.eta) {
285→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
286→            }
287→            if (cfg.showZone && data.zone) {
288→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
289→            }
290→            if (cfg.showDeliveryDays && data.daysOfWeek) {
291→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
292→              html += '<div class="zcc-meta zcc-days">Delivers: ' + esc(days) + '</div>';
293→            }
294→            if (cfg.showCutoffTime && data.cutoffTime) {
295→              var parts = data.cutoffTime.split(':');
296→              var hr = parseInt(parts[0], 10);
297→              var min = parts[1] || '00';
298→              var ampm = hr >= 12 ? 'PM' : 'AM';
299→              var hr12 = hr % 12 || 12;
300→              html += '<div class="zcc-meta zcc-cutoff">Order by ' + hr12 + ':' + min + ' ' + ampm + ' for same-day delivery</div>';
301→            }
302→            if (data.codAvailable === true) {
303→              html += '<div class="zcc-cod zcc-cod--available">\u2713 Cash on Delivery Available</div>';
304→            } else if (data.codAvailable === false) {
305→              html += '<div class="zcc-cod zcc-cod--unavailable">\u2717 COD Not Available</div>';
306→            }
307→            if (data.returnPolicy) {
308→              html += '<div class="zcc-return-policy">\u21a9 ' + esc(data.returnPolicy) + '</div>';
309→            }
310→            html += "</div>";
311→            res.innerHTML = html;
312→          } else {
313→            var html = '<div class="zcc-result fail">' + esc(data.message);
314→            if (cfg.showWaitlistOnFailure) {
315→              html +=
316→                '<div class="zcc-wl">' +
317→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
318→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Join Waitlist</button>' +
319→                "</div>";
320→            }
321→            html += "</div>";
322→            res.innerHTML = html;
323→
324→            if (cfg.showWaitlistOnFailure) {
325→              // Social proof count — insert before email input
326→              if (cfg.showSocialProof && data.waitlistCount && data.waitlistCount > 0) {
327→                var wlSection = document.getElementById(wid + "-wl-email");
328→                if (wlSection && wlSection.parentNode) {
329→                  var spEl = document.createElement('div');
330→                  spEl.className = 'zcc-social-proof';
331→                  var count = data.waitlistCount;
332→                  spEl.textContent = '\uD83D\uDE4B Join ' + count + ' other' + (count !== 1 ? 's' : '') + ' waiting for delivery to your area';
333→                  wlSection.parentNode.insertBefore(spEl, wlSection);
334→                }
335→              }
336→
337→              var wBtn = document.getElementById(wid + "-wl-btn");
338→              if (wBtn) {
339→                wBtn.addEventListener("click", function () {
340→                  var emailEl = document.getElementById(wid + "-wl-email");
341→                  var email = emailEl ? emailEl.value.trim() : "";
342→                  if (!email) { if (emailEl) emailEl.focus(); return; }
343→                  joinWaitlist(zip, email, wBtn);
344→                });
345→              }
346→            }
347→          }
348→
349→          // Block/unblock Add to Cart based on result (if merchant enabled this)
350→          if (cfg.blockCartOnInvalid) {
351→            var ATC_SELECTORS = [
352→              'button[name="add"]',
353→              '.product-form__submit',
354→              '[data-product-add]',
355→              '.btn--add-to-cart',
356→              '.product-form button[type="submit"]',
357→              'button.shopify-payment-button__button',
358→              '.shopify-payment-button button',
359→              'button.product-form__cart-submit'
360→            ].join(',');
361→
362→            try {
363→              var atcBtns = document.querySelectorAll(ATC_SELECTORS);
364→              atcBtns.forEach(function(b) {
365→                if (!b.closest('#zcc-widget, [data-zcc-widget]')) { // Don't touch our own widget's button
366→                  if (data.allowed) {
367→                    b.disabled = false;
368→                    b.style.opacity = '';
369→                    b.title = b.getAttribute('data-zcc-orig-title') || '';
370→                    b.removeAttribute('data-zcc-orig-title');
371→                    b.removeAttribute('data-zcc-blocked');
372→                  } else {
373→                    b.setAttribute('data-zcc-orig-title', b.title || '');
374→                    b.disabled = true;
375→                    b.style.opacity = '0.5';
376→                    b.title = 'Please enter a valid ZIP code to continue';
377→                    b.setAttribute('data-zcc-blocked', 'true');
378→                  }
379→                }
380→              });
381→            } catch(e) { /* DOM query may fail in some contexts */ }
382→          }
383→        })
384→        .catch(function () {
385→          btn.disabled = false;
386→          btn.textContent = btnLabel;
387→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
388→          try {
389→            sessionStorage.setItem('zcc:valid', 'false');
390→            window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
391→          } catch(e) {}
392→        });
393→    }
394→
395→    btn.addEventListener("click", checkZip);
396→    inp.addEventListener("keydown", function (e) {
397→      if (e.key === "Enter") checkZip();
398→    });
399→
400→    // Re-enable buttons when customer clears the input
401→    inp.addEventListener('input', function() {
402→      if (!inp.value.trim() && cfg.blockCartOnInvalid) {
403→        try {
404→          var blocked = document.querySelectorAll('[data-zcc-blocked="true"]');
405→          blocked.forEach(function(b) {
406→            b.disabled = false;
407→            b.style.opacity = '';
408→            b.title = b.getAttribute('data-zcc-orig-title') || '';
409→            b.removeAttribute('data-zcc-blocked');
410→            b.removeAttribute('data-zcc-orig-title');
411→          });
412→          sessionStorage.removeItem('zcc:valid');
413→          sessionStorage.removeItem('zcc:zip');
414→        } catch(e) {}
415→      }
416→    });
417→  }
418→
419→  function joinWaitlist(zip, email, wBtn) {
420→    wBtn.disabled = true;
421→    wBtn.textContent = "Joining\u2026";
422→
423→    fetch(API_BASE + "/api/waitlist", {
424→      method: "POST",
425→      headers: { "Content-Type": "application/json" },
426→      body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
427→    })
428→      .then(function (r) { return r.json(); })
429→      .then(function (data) {
430→        var wlEl = wBtn.closest(".zcc-wl");
431→        if (data.success) {
432→          if (wlEl) wlEl.innerHTML =
433→            '<p style="font-size:13px;margin:6px 0 0">' +
434→            "\u2713 You\u2019ve been added to the waitlist!" +
435→            "</p>";
436→        } else {
437→          wBtn.disabled = false;
438→          wBtn.textContent = "Join Waitlist";
439→        }
440→      })
441→      .catch(function () {
442→        wBtn.disabled = false;
443→        wBtn.textContent = "Join Waitlist";
444→      });
445→  }
446→
447→  // ── Inline position ─────────────────────────────────────────────────────────
448→  function renderInline(cfg, WID, rad) {
449→    injectCss(WID, cfg, rad);
450→    container.id = WID;
451→    container.innerHTML = buildWidgetInner(WID, cfg, cfg.buttonText);
452→    wireWidget(WID, cfg, API_BASE, SHOP);
453→  }
454→
455→  // ── Floating position ────────────────────────────────────────────────────────
456→  function renderFloating(cfg, WID, rad) {
457→    // The original container becomes invisible (just an anchor)
458→    container.style.display = "none";
459→
460→    injectCss(WID, cfg, rad);
461→
462→    // Additional styles for floating UI
463→    var floatCss =
464→      "#" + WID + "-float{position:fixed !important;bottom:20px !important;right:20px !important;z-index:9998 !important;display:flex !important;flex-direction:column !important;align-items:flex-end !important;gap:10px !important}" +
465→      "#" + WID + "-panel{" +
466→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
467→        "box-shadow:0 8px 32px rgba(0,0,0,.18) !important;overflow:hidden !important;" +
468→        "transition:opacity .2s,transform .2s;transform-origin:bottom right" +
469→      "}" +
470→      "#" + WID + "-panel.zcc-hidden{display:none !important}" +
471→      "#" + WID + "-panel .zcc-panel-header{" +
472→        "display:flex !important;align-items:center !important;justify-content:space-between !important;" +
473→        "padding:14px 16px 0 !important;margin-bottom:0 !important" +
474→      "}" +
475→      "#" + WID + "-panel .zcc-panel-close{" +
476→        "background:none !important;border:none !important;cursor:pointer !important;font-size:20px !important;line-height:1 !important;" +
477→        "color:" + cfg.textColor + " !important;opacity:.6;padding:0 4px !important" +
478→      "}" +
479→      "#" + WID + "-panel .zcc-panel-close:hover{opacity:1 !important}" +
480→      "#" + WID + "-trigger{" +
481→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
482→        "border-radius:50px !important;padding:12px 20px !important;font-size:14px !important;font-weight:600 !important;" +
483→        "cursor:pointer !important;box-shadow:0 4px 12px rgba(0,0,0,.2) !important;white-space:nowrap !important" +
484→      "}" +
485→      "#" + WID + "-trigger:hover{opacity:.9 !important}";
486→
487→    var floatStyle = document.createElement("style");
488→    floatStyle.textContent = floatCss;
489→    document.head.appendChild(floatStyle);
490→
491→    // Build floating shell
492→    var floatEl = document.createElement("div");
493→    floatEl.id = WID + "-float";
494→    floatEl.innerHTML =
495→      '<div id="' + WID + '-panel" class="zcc-hidden">' +
496→        '<div class="zcc-panel-header">' +
497→          '<span style="font-size:13px;font-weight:600;color:' + cfg.textColor + '">Delivery Check</span>' +
498→          '<button class="zcc-panel-close" id="' + WID + '-close" type="button" aria-label="Close">&times;</button>' +
499→        '</div>' +
500→        '<div id="' + WID + '" data-zcc-widget="true">' +
501→          buildWidgetInner(WID, cfg, cfg.buttonText) +
502→        '</div>' +
503→      '</div>' +
504→      '<button id="' + WID + '-trigger" type="button">' +
505→        '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="vertical-align:middle;margin-right:6px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
506→        esc(cfg.buttonText || "Check Delivery") +
507→      '</button>';
508→
509→    document.body.appendChild(floatEl);
510→
511→    // Wire toggle
512→    var trigger = document.getElementById(WID + "-trigger");
513→    var panel = document.getElementById(WID + "-panel");
514→    var closeBtn = document.getElementById(WID + "-close");
515→
516→    if (trigger && panel) {
517→      trigger.addEventListener("click", function () {
518→        panel.classList.toggle("zcc-hidden");
519→      });
520→    }
521→    if (closeBtn && panel) {
522→      closeBtn.addEventListener("click", function () {
523→        panel.classList.add("zcc-hidden");
524→      });
525→    }
526→    // Close on outside click
527→    document.addEventListener("click", function (e) {
528→      if (!floatEl.contains(e.target)) {
529→        if (panel) panel.classList.add("zcc-hidden");
530→      }
531→    });
532→
533→    wireWidget(WID, cfg, API_BASE, SHOP);
534→  }
535→
536→  // ── Popup position ───────────────────────────────────────────────────────────
537→  function renderPopup(cfg, WID, rad) {
538→    injectCss(WID, cfg, rad);
539→
540→    var popupCss =
541→      "#" + WID + "-overlay{" +
542→        "display:none !important;position:fixed !important;inset:0 !important;background:rgba(0,0,0,.55) !important;" +
543→        "z-index:9999 !important;align-items:center !important;justify-content:center !important;padding:16px !important" +
544→      "}" +
545→      "#" + WID + "-overlay.zcc-open{display:flex !important}" +
546→      "#" + WID + "-modal{" +
547→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
548→        "max-width:480px !important;width:100% !important;position:relative !important;" +
549→        "box-shadow:0 20px 60px rgba(0,0,0,.3) !important" +
550→      "}" +
551→      "#" + WID + "-modal .zcc-modal-close{" +
552→        "position:absolute !important;top:10px !important;right:14px !important;background:none !important;border:none !important;" +
553→        "font-size:22px !important;line-height:1 !important;cursor:pointer !important;color:" + cfg.textColor + " !important;opacity:.5" +
554→      "}" +
555→      "#" + WID + "-modal .zcc-modal-close:hover{opacity:1 !important}" +
556→      "#" + WID + "-popup-trigger{" +
557→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
558→        "border-radius:" + rad + " !important;padding:10px 24px !important;font-size:14px !important;font-weight:600 !important;" +
559→        "cursor:pointer !important" +
560→      "}" +
561→      "#" + WID + "-popup-trigger:hover{opacity:.9 !important}";
562→
563→    var popupStyle = document.createElement("style");
564→    popupStyle.textContent = popupCss;
565→    document.head.appendChild(popupStyle);
566→
567→    // Trigger button renders in-place (inside the block)
568→    container.innerHTML =
569→      '<button id="' + WID + '-popup-trigger" type="button">' +
570→        esc(cfg.heading) +
571→      '</button>';
572→
573→    // Overlay + modal append to body
574→    var overlay = document.createElement("div");
575→    overlay.id = WID + "-overlay";
576→    overlay.innerHTML =
577→      '<div id="' + WID + '-modal">' +
578→        '<button class="zcc-modal-close" id="' + WID + '-modal-close" type="button" aria-label="Close">&times;</button>' +
579→        '<div id="' + WID + '" data-zcc-widget="true">' +
580→          buildWidgetInner(WID, cfg, cfg.buttonText) +
581→        '</div>' +
582→      '</div>';
583→    document.body.appendChild(overlay);
584→
585→    var trigger = document.getElementById(WID + "-popup-trigger");
586→    var closeBtn = document.getElementById(WID + "-modal-close");
587→    var modal = document.getElementById(WID + "-modal");
588→
589→    function openPopup() { overlay.classList.add("zcc-open"); }
590→    function closePopup() { overlay.classList.remove("zcc-open"); }
591→
592→    if (trigger) trigger.addEventListener("click", openPopup);
593→    if (closeBtn) closeBtn.addEventListener("click", closePopup);
594→
595→    // Close on overlay backdrop click (not modal content)
596→    overlay.addEventListener("click", function (e) {
597→      if (e.target === overlay) closePopup();
598→    });
599→
600→    // Close on Escape key
601→    document.addEventListener("keydown", function (e) {
602→      if (e.key === "Escape") closePopup();
603→    });
604→
605→    wireWidget(WID, cfg, API_BASE, SHOP);
606→  }
607→
608→  function esc(str) {
609→    return String(str)
610→      .replace(/&/g, "&amp;")
611→      .replace(/</g, "&lt;")
612→      .replace(/>/g, "&gt;")
613→      .replace(/"/g, "&quot;");
614→  }
615→
616→  function escAttr(str) {
617→    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
618→  }
619→  } // end init()
620→})();
621→</script>
622→
623→{% endif %}
