  1→import { useState, useCallback, useMemo, useEffect } from "react";
  2→import type {
  3→  ActionFunctionArgs,
  4→  HeadersFunction,
  5→  LoaderFunctionArgs,
  6→} from "react-router";
  7→import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
  8→import { useAppBridge } from "@shopify/app-bridge-react";
  9→import { authenticate } from "../shopify.server";
 10→import { boundary } from "@shopify/shopify-app-react-router/server";
 11→import db from "../db.server";
 12→import { getShopSubscription } from "../billing.server";
 13→import { PLAN_LIMITS } from "../plans";
 14→import {
 15→  Page,
 16→  Layout,
 17→  Card,
 18→  BlockStack,
 19→  InlineStack,
 20→  Text,
 21→  Button,
 22→  TextField,
 23→  Select,
 24→  Modal,
 25→  DataTable,
 26→  EmptyState,
 27→  Divider,
 28→  Box,
 29→  Tooltip,
 30→  Icon,
 31→  Banner,
 32→  Pagination,
 33→  InlineGrid,
 34→} from "@shopify/polaris";
 35→import {
 36→  SearchIcon,
 37→  DeleteIcon,
 38→  PlusIcon,
 39→  EmailIcon,
 40→} from "@shopify/polaris-icons";
 41→
 42→const PAGE_SIZE = 10;
 43→
 44→export const loader = async ({ request }: LoaderFunctionArgs) => {
 45→  const { session } = await authenticate.admin(request);
 46→  const shop = session.shop;
 47→
 48→  const [entries, subscription] = await Promise.all([
 49→    db.waitlistEntry.findMany({
 50→      where: { shop },
 51→      orderBy: { createdAt: "desc" },
 52→    }),
 53→    getShopSubscription(shop),
 54→  ]);
 55→
 56→  const stats = {
 57→    total: entries.length,
 58→    waiting: entries.filter((e) => e.status === "waiting").length,
 59→    notified: entries.filter((e) => e.status === "notified").length,
 60→    converted: entries.filter((e) => e.status === "converted").length,
 61→    uniqueZips: [...new Set(entries.map((e) => e.zipCode))].length,
 62→  };
 63→
 64→  return { entries, stats, subscription };
 65→};
 66→
 67→export const action = async ({ request }: ActionFunctionArgs) => {
 68→  const { session } = await authenticate.admin(request);
 69→  const shop = session.shop;
 70→  const formData = await request.formData();
 71→  const intent = formData.get("intent");
 72→
 73→  if (intent === "add") {
 74→    const email = String(formData.get("email") || "").trim().toLowerCase();
 75→    const zipCode = String(formData.get("zipCode") || "")
 76→      .trim()
 77→      .toUpperCase();
 78→    const note = String(formData.get("note") || "").trim() || null;
 79→
 80→    if (!email || !zipCode) return { error: "Email and zip code are required." };
 81→
 82→    const subscription = await getShopSubscription(shop);
 83→    const limits = PLAN_LIMITS[subscription.planTier];
 84→
 85→    if (limits.maxWaitlist === 0) {
 86→      return { error: "Your current plan does not include waitlist access. Upgrade to Starter or higher." };
 87→    }
 88→
 89→    if (isFinite(limits.maxWaitlist)) {
 90→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
 91→      if (currentCount >= limits.maxWaitlist) {
 92→        return { error: `You have reached the ${limits.maxWaitlist}-entry waitlist limit on your ${limits.label} plan. Upgrade to Pro for unlimited entries.` };
 93→      }
 94→    }
 95→
 96→    try {
 97→      await db.waitlistEntry.create({
 98→        data: { shop, email, zipCode, note },
 99→      });
100→      return { success: true, action: "added" };
101→    } catch {
102→      return { error: "This email is already on the waitlist for this zip code." };
103→    }
104→  }
105→
106→  if (intent === "delete") {
107→    const id = String(formData.get("id"));
108→    await db.waitlistEntry.delete({ where: { id } });
109→    return { success: true, action: "deleted" };
110→  }
111→
112→  if (intent === "update-status") {
113→    const id = String(formData.get("id"));
114→    const status = String(formData.get("status"));
115→    await db.waitlistEntry.update({ where: { id }, data: { status } });
116→    return { success: true, action: "updated" };
117→  }
118→
119→  if (intent === "bulk-notify") {
120→    const zipCode = String(formData.get("zipCode") || "")
121→      .trim()
122→      .toUpperCase();
123→    if (!zipCode) return { error: "Zip code is required." };
124→
125→    const bulkNotifySub = await getShopSubscription(shop);
126→    if (isFinite(PLAN_LIMITS[bulkNotifySub.planTier].maxWaitlist)) {
127→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
128→    }
129→
130→    const updated = await db.waitlistEntry.updateMany({
131→      where: { shop, zipCode, status: "waiting" },
132→      data: { status: "notified" },
133→    });
134→
135→    return {
136→      success: true,
137→      action: "bulk-notify",
138→      count: updated.count,
139→      zipCode,
140→    };
141→  }
142→
143→  if (intent === "notify-zip") {
144→    const zipCode = String(formData.get("zipCode") || "").trim().toUpperCase();
145→    if (!zipCode) return { error: "No ZIP code specified." };
146→
147→    const notifyZipSub = await getShopSubscription(shop);
148→    if (isFinite(PLAN_LIMITS[notifyZipSub.planTier].maxWaitlist)) {
149→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
150→    }
151→
152→    const entries = await db.waitlistEntry.findMany({
153→      where: { shop, zipCode, status: "waiting" },
154→      select: { id: true, email: true },
155→    });
156→
157→    if (entries.length === 0) {
158→      return { action: "notify-zip", zipCode, emails: [] as string[], count: 0 };
159→    }
160→
161→    await db.waitlistEntry.updateMany({
162→      where: { shop, zipCode, status: "waiting" },
163→      data: { status: "notified" },
164→    });
165→
166→    const emails = entries.map((e) => e.email);
167→    return { action: "notify-zip", zipCode, emails, count: emails.length };
168→  }
169→
170→  if (intent === "delete-all-notified") {
171→    const deleted = await db.waitlistEntry.deleteMany({
172→      where: { shop, status: "notified" },
173→    });
174→    return { success: true, action: "deleted-notified", count: deleted.count };
175→  }
176→
177→  return null;
178→};
179→
180→type WaitlistEntry = {
181→  id: string;
182→  email: string;
183→  zipCode: string;
184→  note: string | null;
185→  status: string;
186→  createdAt: string | Date;
187→};
188→
189→export default function WaitlistPage() {
190→  const { entries, stats, subscription } = useLoaderData<typeof loader>();
191→  const fetcher = useFetcher<typeof action>();
192→  const shopify = useAppBridge();
193→  const navigate = useNavigate();
194→
195→  const limits = PLAN_LIMITS[subscription.planTier];
196→  const isFreePlan = limits.maxWaitlist === 0;
197→  const isStarterPlan = isFinite(limits.maxWaitlist) && limits.maxWaitlist > 0;
198→
199→  const [searchQuery, setSearchQuery] = useState("");
200→  const [statusFilter, setStatusFilter] = useState("all");
201→  const [currentPage, setCurrentPage] = useState(1);
202→  const [addModalOpen, setAddModalOpen] = useState(false);
203→  const [notifyModalOpen, setNotifyModalOpen] = useState(false);
204→  const [notifyResultModalOpen, setNotifyResultModalOpen] = useState(false);
205→  const [notifyResult, setNotifyResult] = useState<{
206→    zipCode: string;
207→    emails: string[];
208→    count: number;
209→  } | null>(null);
210→  const [copySuccess, setCopySuccess] = useState(false);
211→
212→  // Form state
213→  const [newEmail, setNewEmail] = useState("");
214→  const [newZipCode, setNewZipCode] = useState("");
215→  const [newNote, setNewNote] = useState("");
216→  const [notifyZip, setNotifyZip] = useState("");
217→
218→  const actionError =
219→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
220→
221→  useEffect(() => {
222→    if (
223→      fetcher.data &&
224→      "action" in fetcher.data &&
225→      fetcher.data.action === "notify-zip"
226→    ) {
227→      const data = fetcher.data as {
228→        action: string;
229→        zipCode: string;
230→        emails: string[];
231→        count: number;
232→      };
233→      setNotifyResult({ zipCode: data.zipCode, emails: data.emails, count: data.count });
234→      setNotifyResultModalOpen(true);
235→    }
236→  }, [fetcher.data]);
237→
238→  const filteredEntries = useMemo(() => {
239→    let filtered = entries as WaitlistEntry[];
240→    if (searchQuery.trim()) {
241→      const q = searchQuery.trim().toLowerCase();
242→      filtered = filtered.filter(
243→        (e) =>
244→          e.email.toLowerCase().includes(q) ||
245→          e.zipCode.toLowerCase().includes(q) ||
246→          (e.note && e.note.toLowerCase().includes(q)),
247→      );
248→    }
249→    if (statusFilter !== "all") {
250→      filtered = filtered.filter((e) => e.status === statusFilter);
251→    }
252→    return filtered;
253→  }, [entries, searchQuery, statusFilter]);
254→
255→  const totalPages = Math.max(1, Math.ceil(filteredEntries.length / PAGE_SIZE));
256→  const paginatedEntries = useMemo(() => {
257→    const start = (currentPage - 1) * PAGE_SIZE;
258→    return filteredEntries.slice(start, start + PAGE_SIZE);
259→  }, [filteredEntries, currentPage]);
260→
261→  const handleSearchChange = useCallback((val: string) => {
262→    setSearchQuery(val);
263→    setCurrentPage(1);
264→  }, []);
265→
266→  const handleFilterChange = useCallback((val: string) => {
267→    setStatusFilter(val);
268→    setCurrentPage(1);
269→  }, []);
270→
271→  const handleAdd = useCallback(() => {
272→    if (!newEmail.trim() || !newZipCode.trim()) return;
273→    const fd = new FormData();
274→    fd.set("intent", "add");
275→    fd.set("email", newEmail);
276→    fd.set("zipCode", newZipCode);
