889→                {
890→                  content: "Close",
891→                  onAction: () => {
892→                    setNotifyResultModalOpen(false);
893→                    setCopySuccess(false);
894→                  },
895→                },
896→              ]
897→        }
898→      >
899→        <Modal.Section>
